package org.ruoyi.service.lawyer;

import lombok.RequiredArgsConstructor;
import org.ruoyi.common.core.exception.ServiceException;
import org.ruoyi.domain.entity.lawyer.*;
import org.springframework.stereotype.Service;
import java.util.*;

/** One checked locator/field contract for review entrants; underlying claim/bank services own all mutations. */
@Service @RequiredArgsConstructor
public class DossierReviewService {
    private final DossierAnchorService anchors;
    private final DossierMaterialService materials;
    private final DossierClaimService claims;
    private final BankStatementService bank;
    private final DossierReviewAudit audit;
    private final org.springframework.jdbc.core.JdbcTemplate jdbc;
    private final DossierEventService events;
    public record Pointer(String objectKind,Long objectId,Long fileVersionId,Integer physicalPageIndex,Long anchorId){}
    public record Field(String key,String label,String value,String original,String type,boolean sensitive){}
    public record View(String objectKind,String objectId,Integer version,String reviewStatus,List<Field> fields,List<DossierAnchorService.Resolved> sources,List<DossierClaimSchema.Link> links,List<DossierReviewAudit.Entry> history,String initialNote){}
    public record Save(int expectedVersion,String action,Map<String,String> fields,List<DossierClaimSchema.Link> sources,String reason){}
    View eventView(DossierAnchorService.Principal p,Long id){
        var detail=events.detail(p.caseId(),id);var c=detail.event();var original=audit.original(p,"event",id);var fields=new ArrayList<Field>();
        add(fields,"title","事件标题",c.getTitle(),original,false);add(fields,"summary","事件简述",c.getSummary(),original,false);add(fields,"eventType","事件类型",c.getEventType(),original,false);
        add(fields,"dateKind","日期确定性",c.getDateKind(),original,false);add(fields,"dateRaw","日期原始表达",c.getDateRaw(),original,false);add(fields,"dateStart","起始日期（可保留月份/年份）",c.getDateStart(),original,false);add(fields,"dateEnd","结束日期（可空）",c.getDateEnd(),original,false);add(fields,"timezone","时区（可空）",c.getTimezone(),original,false);add(fields,"groupLabel","事件分组",c.getGroupLabel(),original,false);add(fields,"sortOrder","同日人工排序",c.getSortOrder().toString(),original,false);
        fields.add(new Field("participants","参与主体（分号分隔，留空保留原值）",BankStatementParser.mask(String.join(";",DossierEventService.participants(c).stream().map(DossierEventService.Participant::label).toList())),original.containsKey("participantsJson")?BankStatementParser.mask(original.get("participantsJson").toString()):null,"text",true));
        return new View("event",c.getId().toString(),c.getVersion(),c.getReviewStatus(),fields,detail.sources(),detail.links(),detail.history(),"保存日期确定性及全部来源；事件核对与主办终核分别记录");
    }
    void saveEvent(Long caseId,Long id,Save request,String state){
        var f=request.fields();if(!Set.of("title","summary","eventType","dateKind","dateRaw","dateStart","dateEnd","timezone","groupLabel","sortOrder","participants").containsAll(f.keySet()))throw new ServiceException("事件系统/出处字段不可修改",400);
        var d=events.detail(caseId,id);var c=d.event();int sort=c.getSortOrder();try{if(f.containsKey("sortOrder"))sort=Integer.parseInt(f.get("sortOrder"));}catch(Exception e){throw new ServiceException("事件排序值无效",400);}
        var participants=f.containsKey("participants")?Arrays.stream(Objects.toString(f.get("participants"),"").split("[;；]")).map(String::strip).filter(v->!v.isBlank()).map(v->new DossierEventService.Participant(null,v)).toList():DossierEventService.participants(c);
        events.edit(caseId,id,new DossierEventService.Edit(request.expectedVersion(),f.getOrDefault("title",c.getTitle()),f.getOrDefault("summary",c.getSummary()),f.getOrDefault("eventType",c.getEventType()),participants,f.getOrDefault("dateKind",c.getDateKind()),f.getOrDefault("dateRaw",c.getDateRaw()),f.getOrDefault("dateStart",c.getDateStart()),f.getOrDefault("dateEnd",c.getDateEnd()),f.getOrDefault("timezone",c.getTimezone()),request.sources()==null?d.links():request.sources(),state,f.getOrDefault("groupLabel",c.getGroupLabel()),sort,request.reason()));
    }
    public List<String> queue(Long caseId,String kind,List<Long> ids){var p=anchors.principal(caseId);if(ids==null||ids.size()>100||ids.stream().anyMatch(id->id==null||id<=0))throw new ServiceException("待核队列范围无效",400);if(ids.isEmpty())return List.of();String table=switch(kind){case "claim"->"lawyer_case_claim";case "bank"->"lawyer_case_bank_row";case "event"->"lawyer_case_event";default->throw new ServiceException("该对象未接入待核队列",503);};var params=new ArrayList<Object>(List.of(p.tenantId(),p.caseId(),p.userId()));params.addAll(ids);var existing=new HashSet<>(jdbc.queryForList("SELECT id FROM "+table+" WHERE tenant_id=? AND case_id=? AND user_id=? AND review_status IN ('pending_review','stale') AND id IN ("+String.join(",",Collections.nCopies(ids.size(),"?"))+")",Long.class,params.toArray()));return ids.stream().distinct().filter(existing::contains).map(Object::toString).toList();}
    public View resolve(Long caseId,Pointer pointer){var p=anchors.principal(caseId);if(pointer==null||pointer.objectKind()==null)throw new ServiceException("缺少复核对象",400);View view;
        if("claim".equals(pointer.objectKind())){if(pointer.objectId()==null)throw new ServiceException("缺少事实对象",400);var detail=claims.detail(caseId,pointer.objectId());var c=detail.claim();var original=audit.original(p,"claim",c.getId());var current=DossierClaimService.values(c);Map<String,String> oldValues=Map.of();if(original.get("valuesJson") instanceof String json){var old=new CaseClaim();old.setValuesJson(json);oldValues=DossierClaimService.values(old);}var fields=new ArrayList<Field>();fields.add(new Field("text","原子事实/摘录",c.getClaimText(),Objects.toString(original.get("claimText"),null),"text",false));for(var entry:new LinkedHashMap<String,String>(){{put("dateRaw","日期原文");put("datePrecision","日期确定性");put("dateStart","日期范围起日");put("dateEnd","日期范围止日");put("amountRaw","金额原文");put("currency","币种");put("name","姓名/主体");}}.entrySet())fields.add(new Field(entry.getKey(),entry.getValue(),current.get(entry.getKey()),oldValues.get(entry.getKey()),entry.getKey().equals("name")?"name":"text",entry.getKey().equals("name")));view=new View("claim",c.getId().toString(),c.getVersion(),c.getReviewStatus(),fields,detail.sources(),claims.linkValues(p,c.getId()),audit.history(p,"claim",c.getId()),original.isEmpty()?"未留存最初字段快照，不把当前值冒充AI原值":"最初候选取自只追加审校记录；原文与当前值独立保留");
        }else if("bank".equals(pointer.objectKind())){if(pointer.objectId()==null)throw new ServiceException("缺少流水对象",400);var row=bank.reviewDetail(caseId,pointer.objectId());var source=bank.source(caseId,row.getId());var resolved=new ArrayList<DossierAnchorService.Resolved>();if(source.verified()&&source.current()&&row.getFragmentStart()>=0){var a=anchors.create(caseId,new DossierAnchorService.Create(row.getFileVersionId(),row.getPageIndex(),"text_offset",row.getFragmentStart(),row.getFragmentEnd(),row.getFragmentText(),null,null,null,false));resolved.add(anchors.resolve(caseId,a.getId()));}var original=audit.original(p,"bank",row.getId());var fields=new ArrayList<Field>();add(fields,"tradeTimeRaw","交易日期原文",row.getTradeTimeRaw(),original,false);add(fields,"amountRaw","金额原文",row.getAmountRaw(),original,false);add(fields,"balanceRaw","余额原文",row.getBalanceRaw(),original,false);add(fields,"direction","收支方向",row.getDirection(),original,false);add(fields,"currency","币种",row.getCurrency(),original,false);add(fields,"summary","摘要",row.getSummary(),original,false);add(fields,"transactionRef","交易号",row.getTransactionRef(),original,false);add(fields,"account","本方账号（留空保留）",row.getAccount(),original,true);add(fields,"counterAccount","对方账号（留空保留）",row.getCounterAccount(),original,true);add(fields,"counterparty","对方户名（留空保留）",row.getCounterparty(),original,true);view=new View("bank",row.getId().toString(),row.getVersion(),row.getReviewStatus(),fields,resolved,List.of(),audit.history(p,"bank",row.getId()),original.isEmpty()?"未留存最初字段快照；当前值不冒充最初AI值":"最初字段取自最早审校快照，旧值不因修改而覆盖");
        }else if("event".equals(pointer.objectKind())){if(pointer.objectId()==null)throw new ServiceException("缺少事件对象",400);view=eventView(p,pointer.objectId());}else if("source".equals(pointer.objectKind())&&pointer.anchorId()!=null){var source=anchors.resolve(caseId,pointer.anchorId());view=new View("source",pointer.anchorId().toString(),null,"read_only",List.of(),List.of(source),List.of(),List.of(),"仅定位原文，不具备事实确认操作");}
        else throw new ServiceException("该模块尚未接入复核；请从已实现的事实或流水入口进入",503);
        if(pointer.anchorId()!=null&&view.sources().stream().noneMatch(s->s.anchor().getId().equals(pointer.anchorId())))throw new ServiceException("来源未关联此复核对象",404);
        if(pointer.fileVersionId()!=null||pointer.physicalPageIndex()!=null){boolean matches=view.sources().stream().anyMatch(s->(pointer.anchorId()==null||s.anchor().getId().equals(pointer.anchorId()))&&(pointer.fileVersionId()==null||s.anchor().getFileVersionId().equals(pointer.fileVersionId()))&&(pointer.physicalPageIndex()==null||s.anchor().getPageIndex().equals(pointer.physicalPageIndex())));if(!matches)throw new ServiceException("直链来源版本/物理页与对象不一致",409);}
        return view;
    }
    static void add(List<Field> fields,String key,String label,String value,Map<String,Object> original,boolean sensitive){Object raw=original.get(sensitive?key+"Raw":key);String old=raw==null?null:raw.toString();fields.add(new Field(key,label,value,sensitive&&old!=null?BankStatementParser.mask(old):old,"text",sensitive));}
    public View save(Long caseId,String kind,Long id,Save request){anchors.principal(caseId);if(request==null||request.fields()==null||request.fields().size()>15||request.fields().values().stream().anyMatch(v->v!=null&&v.length()>5000)||!Set.of("confirm","correct","defer","exclude").contains(Objects.toString(request.action(),"")))throw new ServiceException("复核操作或字段无效",400);BankStatementService.reason(request.reason());
        String state=request.action().equals("confirm")?"confirmed":request.action().equals("exclude")?"excluded":"pending_review";
        if("claim".equals(kind)){if(!Set.of("text","dateRaw","amountRaw","currency","name","datePrecision","dateStart","dateEnd").containsAll(request.fields().keySet()))throw new ServiceException("不允许修改来源或系统字段",400);var p=anchors.principal(caseId);var c=claims.get(p,id,false);var values=new LinkedHashMap<>(DossierClaimService.values(c));request.fields().forEach((key,value)->{if(!key.equals("text"))values.put(key,value);});claims.edit(caseId,id,new DossierClaimService.Edit(request.expectedVersion(),c.getKind(),request.fields().getOrDefault("text",c.getClaimText()),values,request.sources()==null?claims.linkValues(p,id):request.sources(),state,request.reason()));}
        else if("bank".equals(kind)){if(!Set.of("tradeTimeRaw","amountRaw","balanceRaw","direction","currency","summary","transactionRef","account","counterAccount","counterparty").containsAll(request.fields().keySet()))throw new ServiceException("不允许修改来源或系统字段",400);var c=bank.detail(caseId,id);var f=request.fields();bank.edit(caseId,id,new BankStatementService.Edit(request.expectedVersion(),f.getOrDefault("tradeTimeRaw",c.getTradeTimeRaw()),f.getOrDefault("amountRaw",c.getAmountRaw()),f.getOrDefault("direction",c.getDirection()),f.getOrDefault("currency",c.getCurrency()),f.getOrDefault("balanceRaw",c.getBalanceRaw()),f.get("counterAccount"),f.get("counterparty"),f.getOrDefault("transactionRef",c.getTransactionRef()),f.getOrDefault("summary",c.getSummary()),state.equals("excluded")?"rejected":state,!state.equals("excluded"),request.reason(),f.get("account")));}
        else if("event".equals(kind)){saveEvent(caseId,id,request,state);}else throw new ServiceException("该对象未开放修改",400);return resolve(caseId,new Pointer(kind,id,null,null,null));
    }
}
